<?php $parsed=\Platform\Services\CvParser::parse($cv['extractedText']??''); ?>
<?php if($parsed['hasText']): ?><section><p class="muted">Chọn dữ liệu được phát hiện để thêm vào hồ sơ.</p><form data-autofill data-api="/users/me/cv/<?= e($cv['id']) ?>/autofill" data-reload><?php foreach(['skills'=>'Kỹ năng','languages'=>'Ngôn ngữ','certifications'=>'Chứng nhận'] as $key=>$label): ?><h3><?= e($label) ?></h3><?php foreach($parsed[$key] as $value): ?><label><input type="checkbox" name="<?= e($key) ?>[]" value="<?= e($value) ?>" <?= $key==='certifications'?'':'checked' ?>> <?= e($value) ?></label><?php endforeach; endforeach; ?><button>Thêm vào hồ sơ</button></form></section><?php else: ?><p class="muted">CV chưa có nội dung để điền hồ sơ. Hãy tải lên CV có văn bản.</p><?php endif; ?>
